/* eslint-env node */
// Replaces a subscription the push service rotated on its own.
//
// The service worker calls this from a `pushsubscriptionchange` event, where
// there is no Supabase session to authenticate with — so it runs with the
// service role and identifies the row by the old endpoint. That value is
// generated by the push service and known only to this device and us, so it
// acts as the credential. Nothing is created here: an endpoint that is not
// already stored is ignored, so this cannot be used to register a subscription
// against someone else's account.

import { createClient } from '@supabase/supabase-js';

export default async function handler(req, res) {
  if (req.method !== 'POST') return res.status(405).json({ error: 'POST only' });

  const url = process.env.VITE_SUPABASE_URL;
  const key = process.env.SUPABASE_SERVICE_ROLE_KEY;
  if (!url || !key) return res.status(500).json({ error: 'Supabase not configured' });

  let body = req.body;
  if (typeof body === 'string') {
    try { body = JSON.parse(body); } catch { return res.status(400).json({ error: 'Bad JSON' }); }
  }

  const oldEndpoint = body?.oldEndpoint;
  const sub = body?.subscription;
  if (!oldEndpoint || !sub?.endpoint || !sub?.keys?.p256dh || !sub?.keys?.auth) {
    return res.status(400).json({ error: 'Missing subscription details' });
  }

  const admin = createClient(url, key, { auth: { persistSession: false } });

  const { data: existing } = await admin
    .from('push_subscriptions')
    .select('id')
    .eq('endpoint', oldEndpoint)
    .maybeSingle();

  // Unknown endpoint: nothing to rotate. Reported as success so the worker does
  // not retry a subscription we have no record of.
  if (!existing) return res.status(200).json({ rotated: false });

  await admin.from('push_subscriptions').update({
    endpoint: sub.endpoint,
    p256dh:   sub.keys.p256dh,
    auth:     sub.keys.auth,
    failure_count: 0,
  }).eq('id', existing.id);

  return res.status(200).json({ rotated: true });
}
